"""Camera/proprioception-only faucet controller. No simulator state access."""
import numpy as np, json, time, sys
from pathlib import Path
from PIL import Image,ImageDraw
from scipy.spatial.transform import Rotation as Rot
from scipy.optimize import least_squares
from rcb_client import Robot
OUT=Path('/app/output'); r=Robot(); spec=r.spec(); counter=0; obs=None
samples=[]
def record(o,name=None):
 global obs,counter
 obs=o; counter+=1
 d=OUT/(name or f'run{counter:03d}'); o.save(str(d));
 p=np.array(o.meta['proprio']['now']);
 ims=[]
 for c in spec['cameras']:
  if c in o.last:
   im=Image.fromarray(o.last[c]).resize((640,480));ImageDraw.Draw(im).text((8,8),c,fill='yellow');ims.append(im)
 out=Image.new('RGB',(1280,480*((len(ims)+1)//2)))
 for i,im in enumerate(ims):out.paste(im,(i%2*640,i//2*480))
 out.save(str(OUT/'latest.jpg'))
 print(json.dumps({'dir':str(d),'q':p[4:11].tolist(),'eef':p[26:29].tolist(),'base':p[:4].tolist(),'grip':p[11:13].tolist(),'left':o.meta['time_left_s']}),flush=True)
 return o

def state():return np.array(obs.meta['proprio']['now'])
def observe():return record(r.get_obs(include_depth=True,video='none'))
def move(q=None,n=40,grip=None,base=None,torso=0,mode=-1,name=None):
 p=state();start=p[29:36];q=start if q is None else np.array(q)
 a=np.zeros((n,13));a[:,:7]=np.linspace(start,q,n);a[:,7]=p[36] if grip is None else grip;a[:,12]=mode
 if base is not None:a[:,8:11]=base
 a[:,11]=torso
 np.save(OUT/f'actions{counter+1:03d}.npy',a)
 return record(r.submit('joint_position',a,include_depth=True,video='none'),name)

def pose():
 p=state();C=np.array(obs.meta['cameras']['robot0_eye_in_hand']['cam2world_gl']);return p[26:29],C[:3,:3]
def sample():
 p,R=pose();samples.append((state()[4:11].copy(),p.copy(),R.copy()));np.savez(OUT/'samples.npz',q=np.array([s[0] for s in samples]),p=np.array([s[1] for s in samples]),R=np.array([s[2] for s in samples]))
def probe():
 q=state()[4:11].copy();sample()
 for i in range(7):
  t=q.copy();t[i]+=.065;move(t,n=20);sample()
 move(q,n=20)

xyz=np.array([[0,0,.333],[0,0,0],[0,-.316,0],[.0825,0,0],[-.0825,.384,0],[0,0,0],[.088,0,0]])
rx=[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2]
def fk(q):
 T=np.eye(4)
 for i in range(7):
  A=np.eye(4);A[:3,3]=xyz[i];A[:3,:3]=Rot.from_euler('x',rx[i]).as_matrix()@Rot.from_euler('z',q[i]).as_matrix();T=T@A
 return T
fit=None
def calibrate():
 global fit
 def err(x):
  B=Rot.from_rotvec(x[:3]).as_matrix();off=x[6:9];C=Rot.from_rotvec(x[9:12]).as_matrix();errors=[]
  for q,p,R in samples:
   T=fk(q);errors.extend((B@(T[:3,3]+T[:3,:3]@off)+x[3:6]-p).tolist());errors.extend((Rot.from_matrix((B@T[:3,:3]@C).T@R).as_rotvec()*.3).tolist())
  return errors
 best=None
 for z in [0,np.pi/2,np.pi,-np.pi/2]:
  x=np.zeros(12);x[2]=z;x[6:9]=[0,0,.2]
  f=least_squares(err,x,max_nfev=1000)
  if best is None or np.linalg.norm(f.fun)<np.linalg.norm(best.fun):best=f
 fit=best.x;np.save(OUT/'fit.npy',fit);print('FIT',np.linalg.norm(best.fun),fit.tolist(),flush=True)
def predict(q):
 T=fk(q);B=Rot.from_rotvec(fit[:3]).as_matrix();return B@(T[:3,3]+T[:3,:3]@fit[6:9])+fit[3:6], B@T[:3,:3]@Rot.from_rotvec(fit[9:12]).as_matrix()
def goto(p,R=None,n=40,grip=None):
 q0=state()[4:11];R=pose()[1] if R is None else np.array(R);p=np.array(p)
 def err(q):
  pe,re=predict(q);return np.r_[4*(pe-p),Rot.from_matrix(re.T@R).as_rotvec(),.015*(q-q0)]
 sol=least_squares(err,q0,bounds=([-2.89,-1.76,-2.89,-3.07,-2.89,-.017,-2.89],[2.89,1.76,2.89,-.069,2.89,3.75,2.89]),max_nfev=200)
 print('IK',predict(sol.x)[0].tolist(),np.linalg.norm(sol.fun),flush=True);return move(sol.x,n=n,grip=grip)
def point(cam,u,v):
 d=obs.depth[cam];d=d[-1] if d.ndim==3 else d;K=np.array(obs.meta['cameras'][cam]['intrinsic_cv']);T=np.array(obs.meta['cameras'][cam]['cam2world_gl']);z=float(d[v,u]);p=T@np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z,1]);print('POINT',u,v,z,p[:3].tolist(),flush=True);return p[:3]
observe()
print('READY',flush=True)
for line in sys.stdin:
 try:exec(line,globals());print('READY',flush=True)
 except Exception as e:print(type(e).__name__,str(e),flush=True)
